html:
{#- Workplace Rules and Regulations, LPL/HR/05: the rules as HR keeps them (Terms and
    Conditions "Workplace Rules and Regulations", seeded from the issued document and
    revised there), then the new employee's acceptance to sign on the first day. -#}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set rules = frappe.db.get_value("Terms and Conditions", "Workplace Rules and Regulations", "terms") -%}
<style>
	.lpl-rules { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #000; }
	.lpl-rules .ref { text-align: right; font-size: 9.5px; margin: 0; }
	.lpl-rules .logo { text-align: center; margin: 0 0 4px; }
	.lpl-rules h3 { font-size: 13px; font-weight: bold; text-decoration: underline; margin: 6px 0 8px; }
	.lpl-rules h4 { font-size: 11.5px; font-weight: bold; text-decoration: underline; margin: 12px 0 4px; text-transform: uppercase; }
	.lpl-rules ol, .lpl-rules ul { margin: 0 0 6px 18px; padding: 0; }
	.lpl-rules li { margin: 0 0 3px; font-weight: bold; page-break-inside: avoid; }
	.lpl-rules table.sign { width: 100%; margin: 26px 0 10px; }
	.lpl-rules table.sign td { border: none; padding: 0; font-weight: bold; }
	.lpl-rules .acceptance { page-break-inside: avoid; }
</style>
<div class="lpl-rules">
	<p class="ref">LPL/HR/05</p>
	{%- if logo %}<p class="logo"><img src="{{ logo }}" style="max-height: 56px"></p>{% endif %}
	<h3>WORKPLACE RULES AND REGULATIONS</h3>
	{%- if rules %}
	{{ rules }}
	{%- else %}
	<p><em>The rules are kept as the Terms and Conditions "Workplace Rules and Regulations", which this site does not have.</em></p>
	{%- endif %}
	<div class="acceptance">
		<h4>Acceptance by the employee</h4>
		<p><strong>I {{ v(doc.employee_name) or "..............................................................." }} have read and
			understand the above dos and don'ts and I agree to all of them.</strong></p>
		<table class="sign">
			<tr>
				<td style="width: 60%">Sign ......................................................................</td>
				<td>Date {{ frappe.utils.format_date(doc.custom_rules_signed_on) if doc.custom_rules_signed_on else "........................." }}</td>
			</tr>
		</table>
	</div>
	<p class="ref">LPL/HR/05</p>
</div>
